import { getToken } from '@/utils/token'
import { BASE_URL, API_SECRET_KEY } from '@/config'
import router from '@/router'
let isLoggingOut = false
export async function sendApi(data = {}) {
  try {
    const token = await getToken()
    const response = await fetch(`${BASE_URL}/api`, {
      method: 'POST',
      credentials: 'include',
      headers: {
        'Content-Type': 'application/json',
        'X-AUTHORIZATION': `Bearer ${token.token}`,
        'X-API-KEY': API_SECRET_KEY,
        'X-API-KEY-BACK': token.key,
      },
      body: JSON.stringify(data)
    })
    const result = await response.json()
    if (result.code === 401 && result.status === 'error') {
      if (!isLoggingOut) {
        isLoggingOut = true
        localStorage.clear()
        router.push('/')
      }
      window.location.reload()
      throw new Error('Unauthorized')
    }
    return result
  } catch (err) {
    console.error('API Error:', err)
    throw err
  }
}
export async function sendFile(action,data = {}) {
  try {
    const token = await getToken()
    let fetchOptions = {
      method: options.method || 'POST',
      credentials: 'include',
      headers: {
        'X-AUTHORIZATION': `Bearer ${token.token}`,
        'X-API-KEY': API_SECRET_KEY,
        'X-API-KEY-BACK': token.key,
      },
    }
    if (data instanceof File || data instanceof Blob || data instanceof FormData) {
      const formData = new FormData()
      formData.append('action', action)
      formData.append('control', 'upload')
      if (data instanceof FormData) {
        for (let [k, v] of data.entries()) {
          formData.append(k, v)
        }
      } else {
        formData.append('file', data)
      }
      fetchOptions.body = formData
    }
    const response = await fetch(`${BASE_URL}/api`, fetchOptions)
    const result = await response.json()
    if (result.code === 401 && result.status === 'error') {
      if (!isLoggingOut) {
        isLoggingOut = true
        localStorage.clear()
        router.push('/')
      }
      window.location.reload()
      throw new Error('Unauthorized')
    }
    return result
  } catch (err) {
    console.error('API Error:', err)
    throw err
  }
}
